package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Real;
    in attribute io_2 : Real;
    in attribute io_3 : Boolean;
    attribute fanOn : Boolean := false;
    attribute lastDisplayedC : Integer := 0;
    perform action tick {
      first start;
      then if io_3 {
        first start;
        then assign fanOn := io_1 > 30.0;
        then assign lastDisplayedC := (if io_1 >= 0.0 ? RealFunctions::floor(io_1) else -RealFunctions::floor(0.0 - io_1));
      }
    }
    out attribute io_0 : Real = (if fanOn ? 255.0 else 0.0);
    out attribute io_4 : Integer = lastDisplayedC;
  }
  part system : Controller;
}
